#!/system/bin/sh
#=============================================
# 熊二驱动 — 一键刷入脚本 (MT管理器 Root 执行)
# 目标内核: 6.12.23 (GKI 2.0, ARM aarch64)
# 用法: MT管理器长按此文件 → 执行 → 勾选Root
#=============================================

DRIVER_PATH="/data/local/tmp/6.12.23.ko"
MODULE_NAME="mem_tool"
LOG_FILE="/data/local/tmp/driver_flash.log"

echo "============================================"
echo "  熊二驱动 6.12.23 — 一键刷入"
echo "============================================"
echo ""

# ---------- 1. 检查 root ----------
if [ "$(id -u)" != "0" ]; then
    echo "[!] 请以 Root 权限执行此脚本"
    echo "    MT管理器: 长按脚本 → 执行 → 勾选Root"
    exit 1
fi
echo "[√] Root 权限 OK"

# ---------- 2. 检查内核版本 ----------
KERNEL_VER=$(uname -r)
echo "[-] 当前内核: $KERNEL_VER"

case "$KERNEL_VER" in
    6.12.*)
        echo "[√] 内核版本匹配 (6.12.x)"
        ;;
    *)
        echo "[!] 警告: 此驱动编译目标为 6.12.23 内核"
        echo "    当前内核: $KERNEL_VER"
        echo "    可能发生 module_layout CRC 不匹配"
        echo "    若加载失败请使用对应版本的 .ko 文件"
        ;;
esac
echo ""

# ---------- 3. 检查是否已加载 ----------
if lsmod | grep -qE "mem_tool|km_core"; then
    echo "[√] 驱动已加载, 无需重复刷入"
    echo ""
    echo "当前已加载模块:"
    lsmod | grep -E "mem_tool|km_core|Module"
    echo ""
    echo "设备节点:"
    ls -l /dev/ 2>/dev/null | grep -E '^c.*[A-Za-z]{5,8}$' || echo "  (未找到, 请检查 dmesg)"
    exit 0
fi

# ---------- 4. 提取嵌入的驱动文件 ----------
echo "[-] 正在提取驱动文件..."
BASE64_START=$(awk '/^__BASE64_START__$/{print NR+1; exit}' "$0")
if [ -z "$BASE64_START" ]; then
    echo "[!] 脚本格式错误: 找不到驱动数据标记"
    exit 1
fi

tail -n +$BASE64_START "$0" | base64 -d > "$DRIVER_PATH"
if [ $? -ne 0 ] || [ ! -f "$DRIVER_PATH" ] || [ ! -s "$DRIVER_PATH" ]; then
    echo "[!] 驱动提取失败!"
    exit 1
fi
echo "[√] 驱动提取完成 ($(stat -c%s "$DRIVER_PATH" 2>/dev/null || wc -c < "$DRIVER_PATH") bytes)"

# ---------- 5. 加载驱动 ----------
echo "[-] 正在加载内核驱动..."
chmod 644 "$DRIVER_PATH"
insmod "$DRIVER_PATH"

if [ $? -eq 0 ]; then
    echo "[√] 驱动加载成功!"
else
    INSMOD_ERR=$?
    echo "[!] insmod 失败 (exit code: $INSMOD_ERR)"
    echo ""
    echo "可能原因:"
    echo "  1. 内核版本不匹配 (当前: $KERNEL_VER, 驱动目标: 6.12.23)"
    echo "  2. module_layout CRC 不匹配"
    echo "  3. 驱动与当前设备不兼容"
    echo ""
    echo "详细错误 (dmesg):"
    dmesg | tail -5
    echo ""
    echo "dmesg 已追加到: $LOG_FILE"
    dmesg | tail -20 >> "$LOG_FILE"
    rm -f "$DRIVER_PATH"
    exit 1
fi

# ---------- 6. 验证 ----------
echo ""
echo "============================================"
echo "  刷入完成!"
echo "============================================"
echo ""
echo "当前已加载模块:"
lsmod | grep -E "mem_tool|km_core|Module" 2>/dev/null
echo ""
echo "设备节点 (随机名):"
ls -l /dev/ 2>/dev/null | grep -E '^c.*[A-Za-z]{5,8}$' || echo "  (请用 dmesg 查看设备节点名)"
echo ""
echo "驱动文件: $DRIVER_PATH"
echo "日志文件: $LOG_FILE"
echo ""
echo "下次可直接运行一键启动.sh, 无需再次刷入驱动"
echo "============================================"

echo "[$(date)] 驱动刷入成功 | 内核: $KERNEL_VER" >> "$LOG_FILE"

exit 0
__BASE64_START__
